export const PRODUCT_SCOPE = {
  BEER_ADJ: 'Beer + Adjacencies',
  TOTAL_ABI: 'Total ABI',
} as const;

export const EXPORT_PRODUCT_SCOPE_LABEL = {
  BEER_ADJ: 'Beer + Adj',
  TOTAL_ABI: 'Total ABI',
} as const;

type AppliedProductScope = {
  product_scope?: unknown;
};

export const resolveAppliedProductScope = (
  applied?: AppliedProductScope,
): string | undefined => {
  return typeof applied?.product_scope === 'string'
    ? applied.product_scope
    : undefined;
};

export const isBeerAdjProductScope = (
  productScope: string | undefined,
): boolean => productScope === PRODUCT_SCOPE.BEER_ADJ;
